// newInventoryServiceExportReportCommand returns the cobra subcommand for InventoryService.ExportReport.
func newInventoryServiceExportReportCommand(client InventoryServiceClient) *cobra.Command {
	var flagShelf int64
	cmd := &cobra.Command{
		Use:  "export-report",
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			files, err := cmd.Flags().GetStringArray("filename")
			if err != nil {
				return err
			}
			inputs, err := cmd.Flags().GetStringArray("input")
			if err != nil {
				return err
			}
			frags, err := LoadInputs(files, inputs, cmd.InOrStdin())
			if err != nil {
				return err
			}
			if cmd.Flags().Changed("shelf") {
				doc, err := sjson.SetBytes([]byte("{}"), "shelf", flagShelf)
				if err != nil {
					return err
				}
				frags = append(frags, Fragment{Source: "flag --shelf", JSON: doc})
			}
			req := &ExportReportRequest{}
			if err := BuildRequest(req, frags); err != nil {
				return err
			}
			resp, err := client.ExportReport(cmd.Context(), req)
			if err != nil {
				return err
			}
			out, err := marshalJSON(resp)
			if err != nil {
				return err
			}
			_, err = fmt.Fprintln(cmd.OutOrStdout(), string(out))
			return err
		},
	}
	cmd.Flags().Int64Var(&flagShelf, "shelf", flagShelf, "")
	return cmd
}

// ---- Request flags ----

func addRequestFlags(fs *pflag.FlagSet) {
	fs.StringArrayP("filename", "f", nil,
		"Request body from a file (JSON, YAML, or any registered format),\n"+
			"or '-' for stdin. Repeatable; -f files, -i values, and flags\n"+
			"merge in that order.")
	fs.StringArrayP("input", "i", nil,
		"Request body inline (JSON, YAML, or any registered format).\n"+
			"Repeatable; merges after -f files and before flags.")
}

// ---- Request assembly ----

// An InputFormat parses one request-document encoding to JSON.
type InputFormat struct {
	Name  string
	Parse func([]byte) ([]byte, error)
}

// inputFormats is the content-detection order: the first format whose parse
// yields a JSON object claims the input.
var inputFormats = []InputFormat{
	{Name: "json", Parse: func(body []byte) ([]byte, error) {
		if !json.Valid(body) {
			return nil, errors.New("not JSON")
		}
		return body, nil
	}},
	{Name: "yaml", Parse: yaml.YAMLToJSON},
}

// RegisterInputFormat appends a format to the detection order, or replaces
// its namesake. Register before Execute.
func RegisterInputFormat(name string, parse func([]byte) ([]byte, error)) {
	if name == "" || parse == nil {
		panic("RegisterInputFormat: need a format name and a non-nil parser")
	}
	for i, f := range inputFormats {
		if f.Name == name {
			inputFormats[i].Parse = parse
			return
		}
	}
	inputFormats = append(inputFormats, InputFormat{Name: name, Parse: parse})
}

// A Fragment is one request document.
type Fragment struct {
	Source string
	JSON   []byte
}

// LoadInputs returns the request fragments for the -f and -i values in merge
// order: -f documents in argument order ("-" reads stdin), then -i values.
// Content picks each input's format; empty inputs are skipped.
func LoadInputs(files, inline []string, stdin io.Reader) ([]Fragment, error) {
	var out []Fragment
	add := func(source string, raw []byte) error {
		if len(bytes.TrimSpace(raw)) == 0 {
			return nil
		}
		for _, f := range inputFormats {
			body, err := f.Parse(raw)
			if err == nil && bytes.HasPrefix(bytes.TrimSpace(body), []byte("{")) {
				out = append(out, Fragment{Source: source, JSON: body})
				return nil
			}
		}
		formatNames := make([]string, len(inputFormats))
		for i, f := range inputFormats {
			formatNames[i] = f.Name
		}
		return fmt.Errorf("parse %s: not an object in any input format (%s)",
			source, strings.Join(formatNames, ", "))
	}
	for _, name := range files {
		name = strings.TrimSpace(name)
		switch {
		case name == "":
		case name == "-":
			body, err := io.ReadAll(stdin)
			if err != nil {
				return nil, fmt.Errorf("read stdin: %w", err)
			}
			if err := add("stdin", body); err != nil {
				return nil, err
			}
		default:
			body, err := os.ReadFile(name)
			if err != nil {
				return nil, fmt.Errorf("read %s: %w", name, err)
			}
			if err := add(name, body); err != nil {
				return nil, err
			}
		}
	}
	for _, s := range inline {
		if err := add("-i", []byte(s)); err != nil {
			return nil, err
		}
	}
	return out, nil
}

// BuildRequest merges the fragments into req in order. Merging follows
// proto.Merge: populated scalars and oneofs replace, messages merge
// field-wise, repeated fields append, map entries merge per key.
func BuildRequest(req proto.Message, frags []Fragment) error {
	// A fragment is partial by definition; required fields are a property
	// of the assembled request, checked once after the merge.
	for _, frag := range frags {
		next := req.ProtoReflect().New().Interface()
		if err := (protojson.UnmarshalOptions{AllowPartial: true}).Unmarshal(frag.JSON, next); err != nil {
			return fmt.Errorf("decode %s: %w", frag.Source, err)
		}
		proto.Merge(req, next)
	}
	if err := proto.CheckInitialized(req); err != nil {
		return fmt.Errorf("request: %w", err)
	}
	return nil
}

// marshalJSON returns m as compact JSON. json.Compact makes protojson's
// deliberately unstable spacing reproducible.
func marshalJSON(m proto.Message) ([]byte, error) {
	raw, err := protojson.Marshal(m)
	if err != nil {
		return nil, err
	}
	var buf bytes.Buffer
	if err := json.Compact(&buf, raw); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}
